package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/rooms") public class RoomController{private final RoomService service;public RoomController(RoomService s){service=s;}@PostMapping public Mono<RoomView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@Valid@RequestBody CreateRoomRequest r){return service.create(a,r);}@GetMapping public Flux<RoomView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a){return service.list(a);}@PostMapping("/{id}/actions/lock")public Mono<RoomView> lock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.lock(a,id);}@PostMapping("/{id}/actions/unlock")public Mono<RoomView> unlock(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.unlock(a,id);}@PostMapping("/{id}/actions/end")public Mono<RoomView> end(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.end(a,id);}@PostMapping("/{id}/actions/join")public Mono<RoomMembershipView> join(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.join(a,id);}@PostMapping("/{id}/actions/leave")public Mono<RoomMembershipView> leave(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.leave(a,id);}@GetMapping("/{id}/members")public Flux<RoomMembershipView> members(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id){return service.members(a,id);}@PostMapping("/{id}/members/{principal}/actions/remove")public Mono<RoomMembershipView> remove(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id,@PathVariable UUID principal){return service.remove(a,id,principal);}@PostMapping("/{id}/members/{principal}/actions/role")public Mono<RoomMembershipView> role(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id,@PathVariable UUID principal,@RequestParam RoomRole role){return service.changeRole(a,id,principal,role);}@PostMapping("/{id}/members/{principal}/actions/transfer-owner")public Mono<RoomMembershipView> transfer(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID id,@PathVariable UUID principal){return service.transferOwnership(a,id,principal);}}
